action:
if(caller.linkedscene,

    txtadd(img_name, get(caller.name), '_img');
    txtadd(tag_name, get(caller.name), '_tag');


    addhotspot(get(tag_name));
    hotspot[get(tag_name)].loadstyle(skin_hotspotstyle2_tag);
    copy(hotspot[get(tag_name)].ath, caller.ath);
    copy(hotspot[get(tag_name)].atv, caller.atv);
    copy(hotspot[get(tag_name)].html, scene[get(caller.linkedscene)].title);


    addhotspot(get(img_name));
    hotspot[get(img_name)].loadstyle(skin_hotspotstyle2_img);
    copy(hotspot[get(img_name)].ath, caller.ath);
    copy(hotspot[get(img_name)].atv, caller.atv);
    copy(hotspot[get(img_name)].url, scene[get(caller.linkedscene)].thumburl);
);

set(caller.zorder, 50);
tween(caller.alpha, 1.0, 0.2);
if(device.mobile, tween(caller.scale, 0.42, 0.2); , tween(caller.scale, 0.65, 0.2); );

txtadd(img_name, get(caller.name), '_img');
txtadd(tag_name, get(caller.name), '_tag');
if(hotspot[get(img_name)],
    tween(hotspot[get(img_name)].alpha, 1.0, 0.2);
    tween(hotspot[get(tag_name)].alpha, 1.0, 0.2);
);

set(caller.zorder, 40);
tween(caller.alpha, 0.85, 0.2);
if(device.mobile, tween(caller.scale, 0.33, 0.2); , tween(caller.scale, 0.5, 0.2); );

txtadd(img_name, get(caller.name), '_img');
txtadd(tag_name, get(caller.name), '_tag');
if(hotspot[get(img_name)],
    tween(hotspot[get(img_name)].alpha, 0.0, 0.2);
    tween(hotspot[get(tag_name)].alpha, 0.0, 0.2);
);

if(caller.linkedscene,
    hotspot2_onout();
    tween(caller.scale, 0.1, 0.25);
    tween(caller.alpha, 0.0, 0.25);
    looktohotspot(get(caller.name), 65);
    loadscene(get(caller.linkedscene), null, MERGE, BLEND(0.8));
);
